object Solution extends App{val a=new String(System.in.readAllBytes).split("\\s+").tail.map(x=>math.log(x.toDouble)).grouped(2).toSeq;val x=a.map(_(0));val y=a.map(_(1));def s(z:Seq[Double])=z.sum;val n=x.size;val k=(n*s(x.zip(y).map(p=>p._1*p._2))-s(x)*s(y))/(n*s(x.map(z=>z*z))-s(x)*s(x));val l="log n";println("O("+Seq("1",l,"n","n "+l,"n^2","n^2 "+l,"n^3").lift((2*k+.9).toInt).getOrElse("2^n")+")")}
